#!/bin/bash
# One ablation training run on 1 GPU (Stage 1, Stage 2, Stage 3 or the DCPT hold-out). Auto-resumes.
# Run from the repo root, after `export OUT_ROOT=/scratch/p26cs0003/krish/sevdcpt`:
#   sbatch --job-name=abl_c2 --export=ALL,CONFIG=s3_c2_constant.yml ablations/slurm/train.sh
# Templates: ablations/configs/*.yml (generated by ablations/make_configs.py).
#SBATCH --partition=phd
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --gres=gpu:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=48G
#SBATCH --time=5-18:00:00
#SBATCH --output=ablations/logs/%x_%j.out
#SBATCH --error=ablations/logs/%x_%j.err
set -euo pipefail
: "${CONFIG:?set CONFIG=<template>.yml}"
: "${OUT_ROOT:?export OUT_ROOT first, e.g. /scratch/p26cs0003/krish/sevdcpt}"
cd "${SLURM_SUBMIT_DIR}"
[[ -z "${VENV_BASE:-}" && -d "${HOME}/krish/envs/dl_project" ]] && export VENV_BASE="${HOME}/krish/envs"
source slurm/portable/env.sh
source ablations/slurm/_render.sh
render_config "${CONFIG}"

# The DCPT hold-out baseline uses the exact trainer of the DCPT reproduction.
ENTRY=ablations/train.py
if grep -q "^model_type: SRModel" "${RENDERED}"; then ENTRY=basicsr/all_in_one_train.py; fi
echo "[INFO] entry: ${ENTRY}"

# Preflight: data, previous-stage weights and cached conditions exist (unless resuming).
python - "${RENDERED}" <<'PY'
import sys
from pathlib import Path
from basicsr.utils.options import yaml_load
opt = yaml_load(sys.argv[1])
missing = [d[k] for d in opt["datasets"].values() for k in ("manifest", "dataroot_gt", "dataroot_lq")
           if d.get(k) and not Path(d[k]).exists()]
states = Path(opt["path"]["experiments_root"]) / "training_states"
resuming = states.is_dir() and any(states.glob("*.state"))
if not resuming:
    candidates = [opt["path"].get("pretrain_network_g"), opt["path"].get("pretrain_network_extractor"),
                  opt.get("network_g", {}).get("shared_extractor_path")]
    missing += [p for p in candidates if p and not Path(p).is_file()]
if missing:
    sys.exit("[ERROR] missing inputs (previous stage / cache job not finished?):\n  " + "\n  ".join(missing))
print(f"[INFO] preflight OK ({'resuming' if resuming else 'fresh start'})")
PY

RUN_MASTER_PORT="$((20000 + (SLURM_JOB_ID % 40000)))"
python -m torch.distributed.run --nproc_per_node=1 --master-port "${RUN_MASTER_PORT}" \
  "${ENTRY}" -opt "${RENDERED}" --launcher pytorch --auto_resume
